"use client";
import React, { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import ITConsultancySection from "./ITConsultancySection";
import ContactSection2 from "@/components/ContactSection2";

interface TabItem {
  label: string;
  value: string;
  content: React.ReactNode;
}

export default function ServicesTabs() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<string>("db-1");

  // Ref for the main container that holds tabs + content
  const containerRef = useRef<HTMLDivElement>(null);

  const tabs: TabItem[] = [
    { label: "AI & Machine Learning", value: "db-1", content: <ITConsultancySection /> },
    { label: "Web & App Development", value: "db-2", content: <ITConsultancySection /> },
    { label: "Custom Software Development", value: "db-3", content: <ITConsultancySection /> },
    { label: "Ecommerce Development", value: "db-4", content: <ITConsultancySection /> },
    { label: "Digital Marketing", value: "db-5", content: <ITConsultancySection /> },
    { label: "Social Media Marketing", value: "db-6", content: <ITConsultancySection /> },
    { label: "Cloud & DevOps Solutions", value: "db-7", content: <ITConsultancySection /> },
    { label: "BPO & Tech-Enabled Services", value: "db-8", content: <ITConsultancySection /> },
  ];

  // On page load, check if we have a ?service=... in the URL:
  // If so, set that tab active, then scroll to the container
  useEffect(() => {
    if (typeof window !== "undefined") {
      const urlParams = new URLSearchParams(window.location.search);
      const serviceParam = urlParams.get("service");
      if (serviceParam) {
        setActiveTab(serviceParam);

        // Scroll to the container after letting React update the state
        setTimeout(() => {
          containerRef.current?.scrollIntoView({ behavior: "smooth" });
        }, 0);
      }
    }
  }, []);

  // When a tab is clicked from within this page:
  // 1) Set the active tab
  // 2) Update the URL query parameter
  // 3) Smooth scroll to the container
  const handleTabClick = (value: string) => {
    setActiveTab(value);
    router.push(`/services?service=${value}`);
    setTimeout(() => {
      containerRef.current?.scrollIntoView({ behavior: "smooth" });
    }, 0);
  };

  return (
    <>
      <div
        ref={containerRef} // Attach our ref here
        className="w-full relative container mx-auto p-4 md:p-20 md:flex gap-8"
      >
        {/* Left column: Services list */}
        <div className="max-w-xs w-full">
          <div className="space-y-4 p-6 bg-[#F3F7FB]">
            <h2 className="text-base font-semibold">All Services</h2>
            <ul className="flex flex-col space-y-2">
              {tabs.map((tab) => (
                <li key={tab.value}>
                  <button
                    onClick={() => handleTabClick(tab.value)}
                    className={`flex items-center justify-between px-4 py-3 w-full rounded-md text-sm font-medium transition-colors
                      ${
                        activeTab === tab.value
                          ? "bg-blue-600 text-white"
                          : "bg-white text-gray-900 hover:bg-gray-100"
                      }
                    `}
                  >
                    {tab.label}
                    <svg
                      className={`ml-2 h-4 w-4 ${
                        activeTab === tab.value ? "text-white" : "text-gray-400"
                      }`}
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      viewBox="0 0 24 24"
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
                    </svg>
                  </button>
                </li>
              ))}
            </ul>
          </div>
          <div className="h-72 mt-5 relative">
            <Image
              src="/images/mask.png"
              alt="mask image"
              fill
              className="object-cover rounded-xl"
            />
          </div>
        </div>

        {/* Right column: Content for the active tab */}
        <div className="flex-1 mt-6 md:mt-0 bg-gray-50 text-gray-700 rounded-md shadow-sm dark:bg-gray-800 dark:text-gray-300">
          {tabs.map(
            (tab) => tab.value === activeTab && <div key={tab.value}>{tab.content}</div>
          )}
        </div>
      </div>

      <div className="w-full relative container mx-auto p-4 md:p-20">
        <ContactSection2 />
      </div>
    </>
  );
}
